/**
 * Parse a raw configuration value into a positive integer.
 *
 * Accepts the loosely-typed values that configuration sources (environment variables, CLI flags,
 * config files) tend to produce. Whitespace is trimmed. Anything that is not a whole number greater
 * than zero — including the falsy sentinels `'0'`, `'false'`, `'null'`, `'undefined'` and the empty
 * string — resolves to `null`.
 */
export const parsePositiveIntegerConfigValue = (
  value: string | null | undefined
): number | null => {
  if (value == null) {
    return null;
  }

  const trimmed = value.trim();

  if (trimmed === '') {
    return null;
  }

  const parsed = Number(trimmed);

  if (!Number.isInteger(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
};

